CREATE DATABASE IF NOT EXISTS cloudsphere_db CHARACTER SET utf8mb4; USE cloudsphere_db;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150) UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(30),status VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services(id INT AUTO_INCREMENT PRIMARY KEY,service_name VARCHAR(120),service_type VARCHAR(80),provider VARCHAR(80),status VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE servers(id INT AUTO_INCREMENT PRIMARY KEY,server_name VARCHAR(120),operating_system VARCHAR(80),cpu VARCHAR(30),ram VARCHAR(30),storage VARCHAR(30),ip_address VARCHAR(45),status VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE storage_resources(id INT AUTO_INCREMENT PRIMARY KEY,storage_name VARCHAR(120),storage_type VARCHAR(80),capacity VARCHAR(30),used_space VARCHAR(30),available_space VARCHAR(30),status VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cloud_databases(id INT AUTO_INCREMENT PRIMARY KEY,database_name VARCHAR(120),database_engine VARCHAR(80),storage VARCHAR(30),status VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE usage_logs(id INT AUTO_INCREMENT PRIMARY KEY,resource_type VARCHAR(80),resource_name VARCHAR(120),usage_value DECIMAL(5,2),usage_date DATE);
